1	// Command ledger 是本地器具校准台账的命令行入口。
2	//
3	// 用法：
4	//
5	//	ledger -f 台账文件.json <子命令> [参数]
6	//
7	// 数据只保存在 -f 指定的本机文件中；不指定时使用当前目录下的 ledger.json。
8	// 不同文件是互不混入的不同台账，退出后再次打开同一文件可继续查询和操作。
9	package main
10	
11	import (
12		"encoding/json"
13		"errors"
14		"flag"
15		"fmt"
16		"io"
17		"math"
18		"os"
19		"strconv"
20		"strings"
21	
22		"github.com/bengzyyys/calibration-ledger/calibrate"
23	)
24	
25	const usageText = `本地器具校准台账（仅本机，不连接真实实验室）
26	
27	用法：
28	  ledger -f <台账文件> [--json] <子命令> [参数]
29	
30	子命令：
31	  register   登记器具：--id 编号 --name 名称 --allowed 允许绝对误差
32	  status     切换状态：--id 编号 --status 在用|停用|待校准
33	  cert       录入证书：--instrument 器具编号 --number 证书编号 \
34	             --cal-date YYYY-MM-DD --expiry YYYY-MM-DD \
35	             --method 方法 --error 测得误差 --summary 摘要
36	  use        申请使用器具：--id 编号（允许与拒绝都会留痕）
37	  review     按器具核对：--id 编号
38	  list       列出全部登记器具
39	  plan       建立校准计划：--instrument 器具编号 --number 计划编号 \
40	             --date YYYY-MM-DD --note 非空说明
41	  reschedule 计划改期：--number 计划编号 --date 新日期 --reason 非空原因
42	  cancel     取消计划：--number 计划编号 --reason 非空原因
43	  complete   用证书完成计划：--number 计划编号 --certificate 证书编号
44	  todos      校准待办：[--instrument 器具编号]（默认全部未结束计划）
45	
46	通用参数：
47	  -f, --file   台账文件路径（默认 ledger.json）
48	      --json   以 JSON 输出结果
49	
50	退出码：0 成功；1 业务拒绝或未找到；2 参数或读写错误。
51	`
52	
53	// options 是所有子命令共用的全局参数。
54	type options struct {
55		file   string
56		asJSON bool
57	}
58	
59	func main() {
60		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
61	}
62	
63	func run(args []string, stdout, stderr io.Writer) int {
64		if len(args) == 0 {
65			fmt.Fprint(stderr, usageText)
66			return 2
67		}
68		var opts options
69		// 手工解析位于子命令前后的全局参数，flag 包不支持子命令前的散落标志。
70		rest := args
71		for len(rest) > 0 && strings.HasPrefix(rest[0], "-") {
72			a := rest[0]
73			switch {
74			case a == "-f" || a == "--file":
75				if len(rest) < 2 {
76					fmt.Fprintf(stderr, "%s 需要一个值\n", a)
77					return 2
78				}
79				opts.file = rest[1]
80				rest = rest[2:]
81			case strings.HasPrefix(a, "--file="):
82				opts.file = strings.TrimPrefix(a, "--file=")
83				rest = rest[1:]
84			case strings.HasPrefix(a, "-f") && len(a) > 2:
85				opts.file = a[2:]
86				rest = rest[1:]
87			case a == "--json":
88				opts.asJSON = true
89				rest = rest[1:]
90			default:
91				fmt.Fprintf(stderr, "未知全局参数 %s\n\n%s", a, usageText)
92				return 2
93			}
94		}
95		if opts.file == "" {
96			opts.file = "ledger.json"
97		}
98		if len(rest) == 0 {
99			fmt.Fprint(stderr, usageText)
100			return 2
101		}
102		cmd, cmdArgs := rest[0], rest[1:]
103		if cmd == "help" || cmd == "-h" || cmd == "--help" {
104			fmt.Fprint(stdout, usageText)
105			return 0
106		}
107	
108		l, err := calibrate.Open(opts.file)
109		if err != nil {
110			fmt.Fprintln(stderr, "打开台账失败：", err)
111			return 2
112		}
113	
114		switch cmd {
115		case "register":
116			return cmdRegister(l, cmdArgs, opts, stdout, stderr)
117		case "status":
118			return cmdStatus(l, cmdArgs, opts, stdout, stderr)
119		case "cert":
120			return cmdCert(l, cmdArgs, opts, stdout, stderr)
121		case "use":
122			return cmdUse(l, cmdArgs, opts, stdout, stderr)
123		case "review":
124			return cmdReview(l, cmdArgs, opts, stdout, stderr)
125		case "list":
126			return cmdList(l, cmdArgs, opts, stdout, stderr)
127		case "plan":
128			return cmdPlan(l, cmdArgs, opts, stdout, stderr)
129		case "reschedule":
130			return cmdReschedule(l, cmdArgs, opts, stdout, stderr)
131		case "cancel":
132			return cmdCancel(l, cmdArgs, opts, stdout, stderr)
133		case "complete":
134			return cmdComplete(l, cmdArgs, opts, stdout, stderr)
135		case "todos":
136			return cmdTodos(l, cmdArgs, opts, stdout, stderr)
137		default:
138			fmt.Fprintf(stderr, "未知子命令 %q\n\n%s", cmd, usageText)
139			return 2
140		}
141	}
142	
143	// newFlagSet 构造子命令自己的标志集，全局参数仍可写在子命令之后。
144	func newFlagSet(name string, opts *options) *flag.FlagSet {
145		fs := flag.NewFlagSet(name, flag.ContinueOnError)
146		fs.SetOutput(io.Discard)
147		fs.StringVar(&opts.file, "f", opts.file, "台账文件路径")
148		fs.StringVar(&opts.file, "file", opts.file, "台账文件路径")
149		fs.BoolVar(&opts.asJSON, "json", opts.asJSON, "以 JSON 输出")
150		return fs
151	}
152	
153	func parseFloat(stderr io.Writer, raw, field string) (float64, bool) {
154		v, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
155		if err != nil || math.IsNaN(v) || math.IsInf(v, 0) {
156			fmt.Fprintf(stderr, "%s 必须是有限数字\n", field)
157			return 0, false
158		}
159		return v, true
160	}
161	
162	func emit(opts options, stdout, stderr io.Writer, human string, v any) int {
163		if opts.asJSON {
164			raw, err := json.MarshalIndent(v, "", "  ")
165			if err != nil {
166				fmt.Fprintln(stderr, "输出 JSON 失败：", err)
167				return 2
168			}
169			fmt.Fprintln(stdout, string(raw))
170			return 0
171		}
172		fmt.Fprint(stdout, human)
173		return 0
174	}
175	
176	// failBusiness 处理业务拒绝：退出码 1，原记录未被改动。
177	func failBusiness(opts options, stdout, stderr io.Writer, err error, rejected any) int {
178		if opts.asJSON {
179			raw, _ := json.MarshalIndent(rejected, "", "  ")
180			fmt.Fprintln(stdout, string(raw))
181		}
182		fmt.Fprintln(stderr, "已拒绝：", err)
183		return 1
184	}
185	
186	func failIO(stderr io.Writer, err error) int {
187		fmt.Fprintln(stderr, "操作失败：", err)
188		return 2
189	}
190	
191	func cmdRegister(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
192		fs := newFlagSet("register", &opts)
193		id := fs.String("id", "", "器具唯一编号")
194		name := fs.String("name", "", "器具名称")
195		allowed := fs.String("allowed", "", "允许的绝对误差（不小于零的有限数）")
196		if err := fs.Parse(args); err != nil {
197			fmt.Fprintln(stderr, "register 参数错误：", err)
198			return 2
199		}
200		if *id == "" || *name == "" || *allowed == "" {
201			fmt.Fprintln(stderr, "register 必须提供 --id、--name、--allowed")
202			return 2
203		}
204		allowedErr, ok := parseFloat(stderr, *allowed, "允许的绝对误差")
205		if !ok {
206			return 2
207		}
208		inst, err := l.Register(calibrate.RegisterInput{
209			ID: *id, Name: *name, AllowedError: allowedErr,
210		})
211		if err != nil {
212			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
213				return failBusiness(opts, stdout, stderr, err,
214					map[string]any{"accepted": false, "error": err.Error()})
215			}
216			return failIO(stderr, err)
217		}
218		human := fmt.Sprintf("已登记器具 %s（%s），允许绝对误差 %g，状态：%s\n",
219			inst.ID, inst.Name, inst.AllowedError, inst.Status)
220		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "instrument": inst})
221	}
222	
223	func cmdStatus(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
224		fs := newFlagSet("status", &opts)
225		id := fs.String("id", "", "器具编号")
226		status := fs.String("status", "", "在用|停用|待校准")
227		if err := fs.Parse(args); err != nil {
228			fmt.Fprintln(stderr, "status 参数错误：", err)
229			return 2
230		}
231		if *id == "" || *status == "" {
232			fmt.Fprintln(stderr, "status 必须提供 --id、--status")
233			return 2
234		}
235		st, err := calibrate.ParseStatus(*status)
236		if err != nil {
237			fmt.Fprintln(stderr, err)
238			return 2
239		}
240		if err := l.SetStatus(*id, st); err != nil {
241			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
242				return failBusiness(opts, stdout, stderr, err,
243					map[string]any{"accepted": false, "error": err.Error()})
244			}
245			return failIO(stderr, err)
246		}
247		human := fmt.Sprintf("器具 %s 已切换为%s\n", *id, st)
248		return emit(opts, stdout, stderr, human,
249			map[string]any{"accepted": true, "id": *id, "status": st})
250	}
251	
252	func cmdCert(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
253		fs := newFlagSet("cert", &opts)
254		instrument := fs.String("instrument", "", "器具编号")
255		number := fs.String("number", "", "证书编号（全台账唯一）")
256		calDate := fs.String("cal-date", "", "校准日期 YYYY-MM-DD")
257		expiry := fs.String("expiry", "", "有效期截止日 YYYY-MM-DD")
258		method := fs.String("method", "", "校准方法")
259		measured := fs.String("error", "", "测得误差（有限数）")
260		summary := fs.String("summary", "", "证书摘要")
261		if err := fs.Parse(args); err != nil {
262			fmt.Fprintln(stderr, "cert 参数错误：", err)
263			return 2
264		}
265		missing := []string{}
266		for k, v := range map[string]string{
267			"--instrument": *instrument, "--number": *number, "--cal-date": *calDate,
268			"--expiry": *expiry, "--method": *method, "--error": *measured, "--summary": *summary,
269		} {
270			if strings.TrimSpace(v) == "" {
271				missing = append(missing, k)
272			}
273		}
274		if len(missing) > 0 {
275			fmt.Fprintln(stderr, "cert 缺少必填参数：", strings.Join(missing, "、"))
276			return 2
277		}
278		measuredErr, ok := parseFloat(stderr, *measured, "测得误差")
279		if !ok {
280			return 2
281		}
282		cert, duplicate, err := l.AddCertificate(calibrate.CertificateInput{
283			InstrumentID: *instrument,
284			Number:       *number,
285			CalDate:      *calDate,
286			Expiry:       *expiry,
287			Method:       *method,
288			Error:        measuredErr,
289			Summary:      *summary,
290		})
291		if err != nil {
292			if calibrate.IsValidation(err) || calibrate.IsConflict(err) || errors.Is(err, calibrate.ErrNotFound) {
293				return failBusiness(opts, stdout, stderr, err,
294					map[string]any{"accepted": false, "conflict": calibrate.IsConflict(err), "error": err.Error()})
295			}
296			return failIO(stderr, err)
297		}
298		note := "已录入新证书"
299		if duplicate {
300			note = "同号证书且内容一致，返回原证书，未增加历史记录"
301		}
302		verdict := "合格"
303		if math.Abs(cert.Error) > allowedErrorOf(l, cert.InstrumentID) {
304			verdict = "超差"
305		}
306		human := fmt.Sprintf("%s：%s（器具 %s，校准日期 %s，截止日 %s，测得误差 %g，判定：%s）\n",
307			note, cert.Number, cert.InstrumentID, cert.CalDate, cert.Expiry, cert.Error, verdict)
308		return emit(opts, stdout, stderr, human,
309			map[string]any{"accepted": true, "duplicate": duplicate, "verdict": verdict, "certificate": cert})
310	}
311	
312	func allowedErrorOf(l *calibrate.Ledger, id string) float64 {
313		r, err := l.Review(id)
314		if err != nil {
315			return 0
316		}
317		return r.Instrument.AllowedError
318	}
319	
320	func cmdUse(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
321		fs := newFlagSet("use", &opts)
322		id := fs.String("id", "", "器具编号")
323		if err := fs.Parse(args); err != nil {
324			fmt.Fprintln(stderr, "use 参数错误：", err)
325			return 2
326		}
327		if strings.TrimSpace(*id) == "" {
328			fmt.Fprintln(stderr, "use 必须提供 --id")
329			return 2
330		}
331		d, err := l.RequestUse(*id)
332		if err != nil {
333			if errors.Is(err, calibrate.ErrNotFound) || calibrate.IsValidation(err) {
334				return failBusiness(opts, stdout, stderr, err,
335					map[string]any{"accepted": false, "recorded": false, "error": err.Error()})
336			}
337			return failIO(stderr, err)
338		}
339		if !d.Allowed {
340			var sb strings.Builder
341			sb.WriteString(fmt.Sprintf("拒绝使用器具 %s，已记录本次拒绝及原因：\n", *id))
342			for _, r := range d.Reasons {
343				sb.WriteString("  - " + r + "\n")
344			}
345			if opts.asJSON {
346				raw, _ := json.MarshalIndent(map[string]any{
347					"allowed": false, "recorded": true, "decision": d,
348				}, "", "  ")
349				fmt.Fprintln(stdout, string(raw))
350			}
351			fmt.Fprint(stderr, sb.String())
352			return 1
353		}
354		human := fmt.Sprintf("允许使用器具 %s，已记录本次申请。\n", *id)
355		return emit(opts, stdout, stderr, human,
356			map[string]any{"allowed": true, "recorded": true, "decision": d})
357	}
358	
359	func cmdReview(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
360		fs := newFlagSet("review", &opts)
361		id := fs.String("id", "", "器具编号")
362		if err := fs.Parse(args); err != nil {
363			fmt.Fprintln(stderr, "review 参数错误：", err)
364			return 2
365		}
366		if strings.TrimSpace(*id) == "" {
367			fmt.Fprintln(stderr, "review 必须提供 --id")
368			return 2
369		}
370		r, err := l.Review(*id)
371		if err != nil {
372			if errors.Is(err, calibrate.ErrNotFound) {
373				return failBusiness(opts, stdout, stderr, err,
374					map[string]any{"found": false, "error": err.Error()})
375			}
376			return failIO(stderr, err)
377		}
378		var sb strings.Builder
379		fmt.Fprintf(&sb, "器具 %s（%s）\n", r.Instrument.ID, r.Instrument.Name)
380		fmt.Fprintf(&sb, "  允许绝对误差：%g；当前状态：%s\n", r.Instrument.AllowedError, r.Instrument.Status)
381		if r.CanUse {
382			sb.WriteString("  当前能否使用：可以\n")
383		} else {
384			sb.WriteString("  当前能否使用：不可以，原因：\n")
385			for _, reason := range r.Reasons {
386				sb.WriteString("    - " + reason + "\n")
387			}
388		}
389		if r.Latest == nil {
390			sb.WriteString("  最近证书：无\n")
391		} else {
392			fmt.Fprintf(&sb, "  最近证书：%s（校准日期 %s，截止日 %s，判定：%s，%s）\n",
393				r.Latest.Number, r.Latest.CalDate, r.Latest.Expiry,
394				verdictText(r.Latest.Pass), expiryText(r.Latest.Expired))
395		}
396		if len(r.History) == 0 {
397			sb.WriteString("  历史证书：无\n")
398		} else {
399			sb.WriteString("  历史证书（按校准日期由近到远）：\n")
400			for _, c := range r.History {
401				fmt.Fprintf(&sb, "    - %s %s 截止 %s 误差 %g %s %s（%s）\n",
402					c.Number, c.CalDate, c.Expiry, c.Error,
403					verdictText(c.Pass), expiryText(c.Expired), c.Method)
404			}
405		}
406		if len(r.Rejections) == 0 {
407			sb.WriteString("  被拒绝的使用记录：无\n")
408		} else {
409			sb.WriteString("  被拒绝的使用记录（原因为申请当时冻结）：\n")
410			for _, u := range r.Rejections {
411				sb.WriteString("    - " + u.RequestedAt + "\n")
412				for _, reason := range u.Reasons {
413					sb.WriteString("        - " + reason + "\n")
414				}
415			}
416		}
417		if len(r.Plans) == 0 {
418			sb.WriteString("  校准计划：无\n")
419		} else {
420			sb.WriteString("  校准计划（含当前及已结束计划、改期记录与关联证书）：\n")
421			for _, p := range r.Plans {
422				head := fmt.Sprintf("    - %s %s 状态：%s", p.Number, p.PlannedDate, p.Status)
423				if p.Open() {
424					head += "（" + p.Marker + "）"
425				}
426				if p.OriginalDate != p.PlannedDate {
427					head += fmt.Sprintf("，最初计划日期 %s", p.OriginalDate)
428				}
429				head += "，说明：" + p.Note + "\n"
430				sb.WriteString(head)
431				for _, ch := range p.Changes {
432					fmt.Fprintf(&sb, "        改期 %s → %s（%s），原因：%s\n",
433						ch.From, ch.To, ch.ChangedAt, ch.Reason)
434				}
435				if p.Status == calibrate.PlanStatusCanceled {
436					fmt.Fprintf(&sb, "        取消于 %s，原因：%s\n", p.CanceledAt, p.CancelReason)
437				}
438				if p.Status == calibrate.PlanStatusDone {
439					fmt.Fprintf(&sb, "        完成于 %s，证书 %s\n", p.CompletedAt, p.CertificateNumber)
440				}
441			}
442		}
443		return emit(opts, stdout, stderr, sb.String(), r)
444	}
445	
446	func verdictText(pass bool) string {
447		if pass {
448			return "合格"
449		}
450		return "超差"
451	}
452	
453	func expiryText(expired bool) string {
454		if expired {
455			return "已到期"
456		}
457		return "未到期"
458	}
459	
460	func cmdList(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
461		fs := newFlagSet("list", &opts)
462		if err := fs.Parse(args); err != nil {
463			fmt.Fprintln(stderr, "list 参数错误：", err)
464			return 2
465		}
466		instruments := l.Instruments()
467		var sb strings.Builder
468		if len(instruments) == 0 {
469			sb.WriteString("台账中还没有器具。\n")
470		}
471		for _, in := range instruments {
472			fmt.Fprintf(&sb, "%s\t%s\t允许误差 %g\t%s\n", in.ID, in.Name, in.AllowedError, in.Status)
473		}
474		return emit(opts, stdout, stderr, sb.String(),
475			map[string]any{"instruments": instruments, "count": len(instruments)})
476	}
477	
478	// failPlanBusiness 是计划类命令共用的业务拒绝输出（退出码 1）。
479	func failPlanBusiness(opts options, stdout, stderr io.Writer, err error, extra map[string]any) int {
480		resp := map[string]any{"accepted": false, "error": err.Error()}
481		for k, v := range extra {
482			resp[k] = v
483		}
484		return failBusiness(opts, stdout, stderr, err, resp)
485	}
486	
487	func cmdPlan(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
488		fs := newFlagSet("plan", &opts)
489		instrument := fs.String("instrument", "", "器具编号")
490		number := fs.String("number", "", "计划编号（全台账唯一，不可复用）")
491		date := fs.String("date", "", "计划日期 YYYY-MM-DD（不早于今天）")
492		note := fs.String("note", "", "非空计划说明")
493		if err := fs.Parse(args); err != nil {
494			fmt.Fprintln(stderr, "plan 参数错误：", err)
495			return 2
496		}
497		missing := []string{}
498		for k, v := range map[string]string{
499			"--instrument": *instrument, "--number": *number, "--date": *date, "--note": *note,
500		} {
501			if strings.TrimSpace(v) == "" {
502				missing = append(missing, k)
503			}
504		}
505		if len(missing) > 0 {
506			fmt.Fprintln(stderr, "plan 缺少必填参数：", strings.Join(missing, "、"))
507			return 2
508		}
509		p, err := l.CreatePlan(calibrate.PlanInput{
510			Number: *number, InstrumentID: *instrument, Date: *date, Note: *note,
511		})
512		if err != nil {
