514				return failPlanBusiness(opts, stdout, stderr, err, nil)
515			}
516			return failIO(stderr, err)
517		}
518		human := fmt.Sprintf("已为器具 %s 建立校准计划 %s，计划日期 %s，说明：%s\n",
519			p.InstrumentID, p.Number, p.PlannedDate, p.Note)
520		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
521	}
522	
523	func cmdReschedule(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
524		fs := newFlagSet("reschedule", &opts)
525		number := fs.String("number", "", "计划编号")
526		date := fs.String("date", "", "新计划日期 YYYY-MM-DD（不早于今天）")
527		reason := fs.String("reason", "", "非空改期原因")
528		if err := fs.Parse(args); err != nil {
529			fmt.Fprintln(stderr, "reschedule 参数错误：", err)
530			return 2
531		}
532		missing := []string{}
533		for k, v := range map[string]string{
534			"--number": *number, "--date": *date, "--reason": *reason,
535		} {
536			if strings.TrimSpace(v) == "" {
537				missing = append(missing, k)
538			}
539		}
540		if len(missing) > 0 {
541			fmt.Fprintln(stderr, "reschedule 缺少必填参数：", strings.Join(missing, "、"))
542			return 2
543		}
544		p, err := l.ReschedulePlan(*number, *date, *reason)
545		if err != nil {
546			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
547				return failPlanBusiness(opts, stdout, stderr, err, nil)
548			}
549			return failIO(stderr, err)
550		}
551		human := fmt.Sprintf("计划 %s 已改期为 %s（第 %d 次改期）。\n",
552			p.Number, p.PlannedDate, len(p.Changes))
553		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
554	}
555	
556	func cmdCancel(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
557		fs := newFlagSet("cancel", &opts)
558		number := fs.String("number", "", "计划编号")
559		reason := fs.String("reason", "", "非空取消原因")
