616		items, err := l.Todos(*instrument)
617		if err != nil {
618			if errors.Is(err, calibrate.ErrNotFound) {
619				return failBusiness(opts, stdout, stderr, err,
620					map[string]any{"found": false, "error": err.Error()})
621			}
622			return failIO(stderr, err)
623		}
624		var sb strings.Builder
625		if len(items) == 0 {
626			sb.WriteString("无待办。\n")
627		}
628		for _, it := range items {
629			fmt.Fprintf(&sb, "%s\t%s（%s，%s）\t%s\t%s\t%s\n",
630				it.PlanNumber, it.InstrumentID, it.InstrumentName, it.Status,
631				it.PlannedDate, it.Marker, it.Note)
632		}
